args.initScript:
// QA write-guard (navigate_page initScript, agent tab only): blocks every non-GET/HEAD/OPTIONS request
// from the top document (fetch, XHR, sendBeacon) and records it in window.__blockedWrites.
// Needed because the Summary page saves the configuration automatically (POST /modular/configurations/store).
(() => {
  if (window.__qaWriteGuard) return;
  window.__qaWriteGuard = true;
  window.__blockedWrites = [];
  const isWrite = (m) => m && !/^(GET|HEAD|OPTIONS)$/i.test(m);
  const note = (method, url) => window.__blockedWrites.push({ method: String(method).toUpperCase(), url: String(url).split('?')[0].slice(0, 160), at: new Date().toISOString() });
  const origFetch = window.fetch.bind(window);
  window.fetch = (input, init = {}) => {
    const url = typeof input === 'string' ? input : input?.url;
    const method = init.method || (typeof input === 'object' && input?.method) || 'GET';
    if (isWrite(method)) { note(method, url); return Promise.reject(new TypeError('blocked by QA write-guard')); }
    return origFetch(input, init);
  };
  const open = XMLHttpRequest.prototype.open;
  const send = XMLHttpRequest.prototype.send;
  XMLHttpRequest.prototype.open = function (m, u, ...rest) { this.__qaM = m; this.__qaU = u; return open.call(this, m, u, ...rest); };
  XMLHttpRequest.prototype.send = function (body) { if (isWrite(this.__qaM)) { note(this.__qaM, this.__qaU); this.abort(); return; } return send.call(this, body); };
  if (navigator.sendBeacon) navigator.sendBeacon = (url) => { note('BEACON', url); return true; };
})();

// QA harness (agent tab only): simulates the proposed loader fix — collection JSON fetched with cache:'no-cache'
// (forces revalidation, so a heuristically-fresh stale copy is not used). Combine with write-guard.js.
(() => {
  if (window.__qaCollectionsNoCache) return;
  window.__qaCollectionsNoCache = true;
  const prev = window.fetch.bind(window);
  window.fetch = (input, init = {}) => {
    const url = typeof input === 'string' ? input : input?.url;
    if (url && url.includes('/collections/')) return prev(input, { ...init, cache: 'no-cache' });
    return prev(input, init);
  };
})();

args.function:
() => {
  // Click the visible element whose text matches "Skip" (mode "exact": exact | prefix | contains), right panel first.
  const want = "Skip", mode = "exact";
  const txt = (s) => (s || '').replace(/\s+/g, ' ').trim();
  const vis = (e) => { const r = e.getBoundingClientRect(); const cs = getComputedStyle(e); return r.width > 0 && r.height > 0 && cs.visibility !== 'hidden' && cs.display !== 'none' && r.bottom > 0 && r.top < innerHeight; };
  const match = (s) => (mode === 'exact' ? s === want : mode === 'prefix' ? s.startsWith(want) : s.includes(want));
  const rank = { BUTTON: 0, A: 1, INPUT: 1, LABEL: 2 };
  const all = [...document.querySelectorAll('button,a,[role=button],[role=option],[role=radio],[role=tab],[role=menuitem],label,li,[tabindex],div,span,p')]
    .filter((e) => vis(e) && match(txt(e.innerText || e.getAttribute('aria-label') || e.value)));
  if (!all.length) return 'NOT FOUND: ' + want;
  all.sort((a, b) => (a.innerText.length - b.innerText.length) || ((rank[a.tagName] ?? 3) - (rank[b.tagName] ?? 3)));
  const el = all[0].closest('button,a,[role=button],[role=option],[role=radio],[role=tab],label') || all[0];
  if (el.disabled || el.getAttribute('aria-disabled') === 'true') return 'DISABLED: ' + txt(el.innerText).slice(0, 60);
  el.scrollIntoView({ block: 'center' });
  el.click();
  return 'clicked: ' + txt(el.innerText || el.getAttribute('aria-label')).slice(0, 70) + ' <' + el.tagName + '>';
}

